function e(e,t){return Math.max(0,Math.floor(e))*Math.max(0,Math.floor(t))}function t(t,n){if(t>10)return`Máximo de 10 arquivos por operação (você selecionou ${t}).`;if(n>10)return`Máximo de 10 destinos por operação (você selecionou ${n}).`;let r=e(t,n);return r>100?`Máximo de 100 envios por operação (${t} × ${n} = ${r}).`:null}function n(t,n){return e(t,n)>=20}function r(t,n){return`Vai enviar ${e(t,n)} mensagens para ${n} ${n===1?`contato`:`contatos`}. Continuar?`}export{t as n,n as r,r as t};